/* aesthetic buttons v2.24.0 — generated by scripts/build-registry.mjs. */
@import './aesthetic.base.css';

:root {
  --ae-w-medium: 550;
  --ae-radius: 0;
  --ae-space-2: 0.5em;
  --ae-gentle: 480ms;
}

.light,
[data-ae-mode='light'] {
  color-scheme: light;
}

.ae-icon {
width: 1.2em;
  height: 1.2em;
  stroke: currentColor;
  stroke-width: 1.5;
  stroke-linecap: round;
  stroke-linejoin: round;
  fill: none;
  vertical-align: -0.2em;
}

.ae-button {
display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--ae-space-2);
  background: var(--ae-ink);
  border: 1px solid var(--ae-ink);
  border-radius: var(--ae-radius);
  color: var(--ae-surface);
  font-weight: var(--ae-w-medium);
  padding: 0.55em 1.5em;
  min-height: 44px;
  cursor: pointer;
  transition:
    opacity var(--ae-quick) var(--ae-ease),
    background-color var(--ae-quick) var(--ae-ease),
    transform var(--ae-quick) var(--ae-ease);
}

.ae-button:hover {
opacity: 0.9;
}

.ae-button:active {
transform: translateY(1px) scale(0.99);
}

.ae-button:disabled {
cursor: default;
  opacity: 0.7;
  transform: none;
}

.ae-button-quiet {
background: transparent;
  color: var(--ae-ink);
}

.ae-button-quiet:hover {
background: var(--ae-wash);
  opacity: 1;
}

.ae-button-compact {
font-size: 13px;
  padding: 0.35em 1em;
  min-height: 32px;
}

.ae-send {
position: relative;
  overflow: hidden;
}

.ae-send .ae-send-label,
.ae-send .ae-send-done {
display: inline-flex;
  align-items: center;
  gap: var(--ae-space-2);
  transition:
    opacity var(--ae-gentle) var(--ae-ease),
    transform var(--ae-gentle) var(--ae-ease);
}

.ae-send .ae-send-done {
position: absolute;
  inset: 0;
  justify-content: center;
  opacity: 0;
  transform: translateY(45%);
}

.ae-send.is-sent .ae-send-label {
opacity: 0;
  transform: translateY(-55%);
}

.ae-send.is-sent .ae-send-done {
opacity: 1;
  transform: translateY(0);
}

.ae-send.is-sent,
.ae-send.is-sent:disabled {
opacity: 1;
}

/* the send moment: resolve once, persist, and say so. Call
   window.aeSend(button, 'Sent') on success — it flips the costume,
   disables the control (success is never rewound), and announces the
   resolved state to assistive tech: the aria-hidden done layer is
   silent on its own, so a live region speaks for it.

   Forms marked data-ae-demo resolve on submit without a network —
   the site's demo hook; real consumers call aeSend from their own
   submit handling. */
(() => {
  if (window.aeSend) return;
  const live = document.createElement('span');
  live.className = 'ae-sr';
  live.setAttribute('role', 'status');
  (document.body || document.documentElement).appendChild(live);

  window.aeSend = (btn, done) => {
    if (!btn || btn.classList.contains('is-sent')) return;
    btn.classList.add('is-sent');
    btn.disabled = true;
    live.textContent = '';
    requestAnimationFrame(() => {
      live.textContent =
        done ||
        btn.dataset.aeDone ||
        (btn.querySelector('.ae-send-done') || {}).textContent ||
        'Done';
    });
  };

  document.querySelectorAll('form[data-ae-demo]').forEach((form) => {
    form.addEventListener('submit', (e) => {
      e.preventDefault();
      window.aeSend(form.querySelector('.ae-send'));
    });
  });
})();
